def color_histogram(coloring):
    from collections import Counter
    return dict(Counter(coloring))

def test_semantic_equivalence(c1, c2):
    from collections import Counter
    from itertools import permutations
    n = len(c1)
    if Counter(c1) != Counter(c2):
        return False, None
    for perm in permutations(range(n)):
        if all(c1[i] == c2[perm[i]] for i in range(n)):
            return True, list(perm)
    return False, None

def semantic_distance(c1, c2):
    from itertools import permutations
    n = len(c1)
    return min(sum(1 for i in range(n) if c1[i] != c2[perm[i]]) for perm in permutations(range(n)))

def count_classes(n, k):
    from itertools import permutations
    import math
    total = 0
    for perm in permutations(range(n)):
        visited = [False]*n
        cycles = 0
        for i in range(n):
            if not visited[i]:
                cycles += 1
                j = i
                while not visited[j]:
                    visited[j] = True
                    j = perm[j]
        total += k**cycles
    return total // math.factorial(n)
